pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address realOwner) public {
        vm.assume(realOwner != address(0));
        address proxy = address(c);
        address impl = address(new C());
        // Because C is a UUPS proxy, it delegates calls to itself via upgrade.
        // We impersonate the existing owner (address(0) after constructor) to upgrade the proxy
        // to a new implementation, and then initialize it with the fuzzed owner.
        // After initialization, owner() must return the realOwner.
        vm.prank(address(0));
        C(proxy).upgradeToAndCall(impl, abi.encodeWithSelector(C.initialize.selector, uint256(0), uint256(1), "test", address(0xdead)));

        vm.prank(address(0));
        C(proxy).transferOwnership(realOwner);
        vm.prank(realOwner);
        C(proxy).acceptOwnership();

        address returnedOwner = C(proxy).owner();
        assertTrue(returnedOwner == realOwner);
    }
}

