pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool pausedState) public {
        // Ensure the contract is initialized and we can pause/unpause to set the state
        // We rely on the fact that the initializer sets _paused to false, and we can toggle it
        // via the owner (which is this test contract after setUp).
        vm.assume(uint256(pausedState ? 1 : 0) <= 1); // keep it logical, but fuzzer supplies both values

        // Set the contract into the desired paused state
        if (pausedState) {
            // contract starts unpaused; to set it to paused, we need to call pause()
            c.pause();
        } else {
            // contract might be in any state due to fuzzer; ensure it's unpaused
            if (c.paused()) {
                c.unPause();
            }
        }

        // The invariant: c.paused() must return exactly the value we set (pausedState)
        assertTrue(c.paused() == pausedState);
    }
}

