pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(0));
        // Ensure sender is an EOA so low-level calls issued by Ownable etc. succeed
        // The onlyOwner modifier uses OwnableUpgradeable which checks owner().
        // Since setUp deploys c and c's initializer sets msg.sender as owner,
        // we must prank as the owner to call pause/unpause.
        address owner = c.owner();
        vm.startPrank(owner);
        // Pause the contract
        c.pause();
        bool pausedAfterPause = c.paused();
        // Unpause
        c.unPause();
        bool pausedAfterUnpause = c.paused();
        vm.stopPrank();
        // The invariant: paused() must return true after pause() and false after unPause().
        // The mutant negates the return value, so it will return false after pause() and true after unPause().
        assertTrue(pausedAfterPause && !pausedAfterUnpause);
    }
}

