    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address royaltyRecipient, uint256 tokenId) public {
        vm.assume(royaltyRecipient != address(0));

        // Initialize via the UUPS proxy pattern (the implementation is not a proxy but has initializer semantics).
        // Since we deploy c as implementation directly, we call the initializer manually.
        // The tokenIdCounter starts at 1, so any tokenId that will have no specific royalty config is fine.
        c.initialize(1, 1, "test", royaltyRecipient);

        // getRoyalties expects that initializeRoyalties has been called during initialization
