        // which would get an explicit config only if someone called updateRoyalties.
        // No explicit royalty is set, so getRoyalties returns the default.
        C.RoyaltyConfiguration memory cfg = c.getRoyalties(tokenId);

        // The rule: default royalty configuration must have royaltyBPS == 500
        assertEq(cfg.royaltyBPS, 500, "default royaltyBPS must be 500");
    }
